-- =====================================================================
-- بيانات تجريبية للتطوير فقط (is_demo = true)
-- مهارات وأسئلة نموذجية لتجربة التدريب، تُستبدل بالأسئلة المعتمدة من المعلمتين.
-- الحذف الكامل: supabase/demo/purge_demo.sql
-- =====================================================================
insert into classes (id, name, is_demo) values ('d0000000-0000-0000-0000-000000000001', 'فصل تجريبي', true)
on conflict (id) do nothing;

insert into skills (domain_id, topic_id, code, name_ar, sort_order, is_demo)
select t.domain_id, t.id, x.code, x.name_ar, x.ord, true
from (values
  ('integers', 'DEMO-INT-01', 'جمع الأعداد الصحيحة وطرحها', 1),
  ('expressions_equations', 'DEMO-ALG-01', 'حل معادلات بخطوة واحدة', 2),
  ('ratio_percent', 'DEMO-PCT-01', 'إيجاد النسبة المئوية من عدد', 3)
) as x(topic, code, name_ar, ord)
join topic_areas t on t.code = x.topic
on conflict (code) do nothing;

with s as (select id, code from skills where code like 'DEMO-%')
insert into questions (skill_id, cognitive, difficulty, qtype, prompt, options, correct_answer, hint, explanation, solution_steps, common_errors, remedial_activity, status, is_demo)
select s.id, q.cog::cognitive_domain, q.diff, q.qt::question_type, q.prompt, q.opts::jsonb, q.ans::jsonb, q.hint, q.expl, q.steps::jsonb, q.errs::jsonb, q.rem, 'published', true
from (values
  ('DEMO-INT-01','knowing',1,'mcq','ما ناتج: (−7) + 4 ؟','[{"id":"a","text":"−11"},{"id":"b","text":"−3"},{"id":"c","text":"3"},{"id":"d","text":"11"}]','{"value":"b"}',
   'البداية من −7 على خط الأعداد، ثم 4 خطوات نحو اليمين.','عند جمع عددين مختلفين في الإشارة نطرح القيمتين المطلقتين ونأخذ إشارة الأكبر قيمة مطلقة.',
   '["القيمة المطلقة للعدد −7 هي 7، وللعدد 4 هي 4","7 − 4 = 3","الإشارة سالبة لأن 7 أكبر من 4، فالناتج −3"]','[{"answer":"a","error_type":"جمع القيم المطلقة مع إهمال اختلاف الإشارة"},{"answer":"c","error_type":"إهمال الإشارة"}]','تمثيل خمس عمليات جمع على خط الأعداد'),
  ('DEMO-INT-01','applying',2,'mcq','كانت درجة الحرارة صباحًا −5، ثم ارتفعت 9 درجات. كم أصبحت درجة الحرارة؟','[{"id": "a", "text": "−14"}, {"id": "b", "text": "4"}, {"id": "c", "text": "14"}, {"id": "d", "text": "−4"}]','{"value":"b"}',
   'الارتفاع يعني الجمع: (−5) + 9','نجمع −5 و 9 فنحصل على 4.','["الارتفاع يعني إضافة: (−5) + 9","9 − 5 = 4","الإشارة موجبة لأن 9 أكبر، فالناتج 4"]','[{"answer":"a","error_type":"عكس معنى الارتفاع"},{"answer":"c","error_type":"جمع القيم المطلقة"}]',null),
  ('DEMO-INT-01','knowing',1,'mcq','ما ناتج: 6 − (−2) ؟','[{"id": "a", "text": "4"}, {"id": "b", "text": "−8"}, {"id": "c", "text": "8"}, {"id": "d", "text": "−4"}]','{"value":"c"}',
   'طرح عدد سالب يساوي جمع معكوسه.','6 − (−2) = 6 + 2 = 8','["طرح −2 يساوي جمع 2","6 + 2 = 8"]','[{"answer":"a","error_type":"معاملة طرح السالب كطرح موجب"}]',null),
  ('DEMO-INT-01','reasoning',3,'true_false','ناتج طرح عدد سالب من عدد موجب يكون دائمًا عددًا موجبًا.','[]','{"value":true}',
   'مثالان للتحقق: 3 − (−1) و 1 − (−10).','لأن أ − (−ب) = أ + ب، ومجموع عددين موجبين موجب دائمًا.','["أ − (−ب) = أ + ب","أ موجب و ب موجب","إذن المجموع موجب دائمًا"]','[]',null),
  ('DEMO-ALG-01','knowing',1,'mcq','ما حل المعادلة: س + 7 = 12 ؟','[{"id":"a","text":"19"},{"id":"b","text":"5"},{"id":"c","text":"−5"},{"id":"d","text":"84"}]','{"value":"b"}',
   'ما العدد الذي إذا أضفنا إليه 7 صار 12؟','نطرح 7 من الطرفين فنحصل على س = 5.','["س + 7 − 7 = 12 − 7","س = 5"]','[{"answer":"a","error_type":"جمع بدل الطرح"}]',null),
  ('DEMO-ALG-01','applying',2,'mcq','حل المعادلة: 4س = −20','[{"id": "a", "text": "5"}, {"id": "b", "text": "−5"}, {"id": "c", "text": "−80"}, {"id": "d", "text": "−16"}]','{"value":"b"}',
   'قسمة الطرفين على 4.','4س ÷ 4 = −20 ÷ 4، إذن س = −5.','["نقسم الطرفين على 4","س = −20 ÷ 4","س = −5"]','[{"answer":"a","error_type":"خطأ في إشارة ناتج القسمة"},{"answer":"c","error_type":"ضرب بدل القسمة"}]',null),
  ('DEMO-ALG-01','applying',2,'mcq','حل المعادلة: س ÷ 3 = 6','[{"id": "a", "text": "2"}, {"id": "b", "text": "9"}, {"id": "c", "text": "18"}, {"id": "d", "text": "3"}]','{"value":"c"}',
   'العملية العكسية للقسمة هي الضرب.','نضرب الطرفين في 3 فنحصل على س = 18.','["نضرب الطرفين في 3","س = 6 × 3 = 18"]','[{"answer":"a","error_type":"قسمة بدل الضرب"}]',null),
  ('DEMO-ALG-01','reasoning',3,'mcq','أيّ المعادلات الآتية حلها س = 3 ؟','[{"id":"a","text":"2س = 5"},{"id":"b","text":"س − 3 = 0"},{"id":"c","text":"س + 3 = 0"},{"id":"d","text":"3س = 1"}]','{"value":"b"}',
   'التعويض بـ س = 3 في كل معادلة ثم التحقق.','عند التعويض: 3 − 3 = 0، فالمعادلة صحيحة.','["نعوض س = 3 في كل خيار","2(3)=6≠5 ، 3−3=0 ✓ ، 3+3=6≠0 ، 3(3)=9≠1"]','[{"answer":"c","error_type":"إهمال الإشارة"}]',null),
  ('DEMO-PCT-01','knowing',1,'mcq','ما 10% من 250 ؟','[{"id": "a", "text": "2.5"}, {"id": "b", "text": "25"}, {"id": "c", "text": "250"}, {"id": "d", "text": "2500"}]','{"value":"b"}',
   '10% تعني جزءًا من عشرة.','250 ÷ 10 = 25','["10% = 10 ÷ 100 = 0.1","250 × 0.1 = 25"]','[{"answer":"d","error_type":"ضرب في 10 بدل القسمة"}]',null),
  ('DEMO-PCT-01','applying',2,'mcq','سعر حقيبة 80 ريالًا وعليها خصم 25%. كم ستدفع المشترية؟','[{"id":"a","text":"20"},{"id":"b","text":"55"},{"id":"c","text":"60"},{"id":"d","text":"75"}]','{"value":"c"}',
   'قيمة الخصم أولًا، ثم طرحها من السعر.','الخصم 20 ريالًا، فالمدفوع 60 ريالًا.','["25% من 80 = 80 ÷ 4 = 20","80 − 20 = 60"]','[{"answer":"a","error_type":"الاكتفاء بقيمة الخصم"},{"answer":"b","error_type":"طرح النسبة رقمًا"}]',null),
  ('DEMO-PCT-01','applying',2,'mcq','ما 20% من 45 ؟','[{"id": "a", "text": "4.5"}, {"id": "b", "text": "20"}, {"id": "c", "text": "9"}, {"id": "d", "text": "25"}]','{"value":"c"}',
   '20% تساوي خُمس العدد.','45 ÷ 5 = 9','["20% = 1/5","45 ÷ 5 = 9"]','[]',null),
  ('DEMO-PCT-01','reasoning',3,'true_false','50% من 30 تساوي 30% من 50.','[]','{"value":true}',
   'حساب كل طرف على حدة.','كلاهما يساوي 15، لأن (50 × 30) ÷ 100 = (30 × 50) ÷ 100.','["50% من 30 = 15","30% من 50 = 15","إذن العبارة صحيحة"]','[]',null)
) as q(skill_code, cog, diff, qt, prompt, opts, ans, hint, expl, steps, errs, rem)
join s on s.code = q.skill_code;
